--                       COGRAFIYA
--
--  BU FAYL ELLE YAZILMIR - tools/fenn11.py yaradir:
--      python3 tools/fenn11.py
--
--  Fizika 6 + Kimya 6 + Biologiya 8 + Cografiya 8 = 28 movzu x 30 = 840.
--  ext_key: fiz11-/kim11-/bio11-/cog11-...
--  ON SERT: 49_movzular_orta11.sql islenmis olmalidir.
--  SONRA:   05_grants.sql yeniden islet.
-- =====================================================================

do $$
begin
  if not exists (select 1 from public.topics t join public.subjects s
      on s.id = t.subject_id
     where (s.slug, t.slug) in (('fizika','fiz-11-optika'),
                                ('kimya','kim-11-polimer'),
                                ('biologiya','bio-11-viruslar'),
                                ('cografiya','cog-11-qloballasma'))
     having count(*) = 4) then
    raise exception 'ONCE 49_movzular_orta11.sql isledilmelidir.';
  end if;
end $$;

delete from public.question_options o
 using public.questions q
 where o.question_id = q.id
   and q.owner_type = 'platform'
   and (q.ext_key like 'fiz11-%' or q.ext_key like 'kim11-%'
        or q.ext_key like 'bio11-%' or q.ext_key like 'cog11-%');

